const DESKTOP = 1440 / 900
const NARROW = 390 / 844
const KNOTS = [
  [0.735, 0], [0.795, 7.2], [0.835, 9.6],
  [0.87, 24.6], [0.884, 25], [0.902, 31.8],
  [0.905, 32], [0.94, 43],
] as const
const CAMERA_SEAMS = [
  0.735, 0.795, 0.835, 0.846, 0.863, 0.874, 0.884, 0.905, 0.925, 0.94,
] as const
const at = (progress: number, aspect = DESKTOP) =>
  samplePrivateInspection(progress, aspect, createPrivateInspectionSample())

/** Locate a subject seam without assuming a particular interpolation polynomial. */
function progressAtTime(time: number): number {
  let low = 0.735
  let high = 0.94
  const out = createPrivateInspectionSample()
  for (let i = 0; i < 55; i++) {
    const mid = (low + high) / 2
    if (samplePrivateInspection(mid, DESKTOP, out).subjectTime < time) low = mid
    else high = mid
  }
  return (low + high) / 2
}

function positionDistance(a: PrivateInspectionSample, b: PrivateInspectionSample): number {
  return Math.hypot(a.camera.px - b.camera.px, a.camera.py - b.camera.py, a.camera.pz - b.camera.pz)
}

/** Angular change of the actual look direction, independent of translation. */
function orientationAngle(a: PrivateInspectionSample, b: PrivateInspectionSample): number {
  const dot = a.camera.dx * b.camera.dx + a.camera.dy * b.camera.dy + a.camera.dz * b.camera.dz
  return Math.acos(Math.max(-1, Math.min(1, dot)))
}

describe('JG-038 private InspectionDirector C1', () => {
  it.each([NaN, Infinity, -Infinity])('rejects nonfinite inputs %s before changing caller output', (invalid) => {
    const out = at(0.815)
    const before = structuredClone(out)
    expect(() => samplePrivateInspection(invalid, DESKTOP, out)).toThrow(/finite/)
    expect(out).toEqual(before)
    expect(() => samplePrivateInspection(0.815, invalid, out)).toThrow(/finite/)
    expect(out).toEqual(before)
    expect(() => samplePrivateInspection(-100, invalid, out)).toThrow(/finite/)
    expect(out).toEqual(before)
  })

  it('clamps finite overscroll and canonicalizes negative zero', () => {
    expect(at(-100)).toEqual(at(0))
    expect(at(Number.MAX_VALUE)).toEqual(at(1))
    expect(at(-0)).toEqual(at(0))
    expect(Object.is(at(-0).progress, -0)).toBe(false)
  })

  it('hits every canonical master-time knot exactly and holds constant endpoints', () => {
    for (const [progress, time] of KNOTS) expect(at(progress).subjectTime).toBe(time)
    for (const progress of [0, 0.2, 0.734, 0.735]) {
      const sample = at(progress)
      expect(sample.subjectTime).toBe(0)
      expect(sample.cameraTime).toBe(0)
      expect(sample.kinematics).toEqual(at(0.735).kinematics)
      expect(sample.camera).toEqual(at(0.735).camera)
    }
    for (const progress of [0.94, 0.95, 1]) {
      const sample = at(progress)
      expect(sample.subjectTime).toBe(43)
      expect(sample.cameraTime).toBe(43)
      expect(sample.kinematics).toEqual(at(0.94).kinematics)
      expect(sample.camera).toEqual(at(0.94).camera)
    }
  })

  it('maps subject time monotonically without overshoot or internal stops', () => {
    const out = createPrivateInspectionSample()
    let previousTime = -1
    let previousCameraTime = -1
    for (let i = 0; i <= 2000; i++) {
      const sample = samplePrivateInspection(i / 2000, DESKTOP, out)
      expect(sample.subjectTime).toBeGreaterThanOrEqual(previousTime)
      expect(sample.subjectTime).toBeGreaterThanOrEqual(0)
      expect(sample.subjectTime).toBeLessThanOrEqual(43)
      expect(sample.cameraTime).toBeGreaterThanOrEqual(previousCameraTime)
      previousTime = sample.subjectTime
      previousCameraTime = sample.cameraTime
    }
    for (const [progress] of KNOTS.slice(1, -1)) {
      const rate = (at(progress + 1e-6).subjectTime - at(progress - 1e-6).subjectTime) / 2e-6
      expect(rate).toBeGreaterThan(1)
    }
  })

  it.each([DESKTOP, NARROW])('retraces forward/reverse/seek/reload and exact holds at aspect %s', (aspect) => {
    const checkpoints = [0, 0.735, 0.78, 0.795, 0.801, 0.817, 0.831, 0.835, 0.84, 0.87, 0.89, 0.905, 0.94, 1]
    const expected = new Map(checkpoints.map(p => [p, at(p, aspect)]))
    const out = createPrivateInspectionSample()
    const seeks = [...checkpoints.filter((_, i) => i % 2), ...checkpoints.filter((_, i) => !(i % 2))]
    for (const order of [checkpoints, [...checkpoints].reverse(), seeks]) {
      for (const p of order) {
        expect(samplePrivateInspection(p, aspect, out)).toEqual(expected.get(p))
        for (let hold = 0; hold < 5; hold++) {
          expect(samplePrivateInspection(p, aspect, out)).toEqual(expected.get(p))
        }
        expect(at(p, aspect)).toEqual(expected.get(p))
      }
    }
  })

  it('keeps outputs independent and reuses caller objects and depth storage', () => {
    const first = at(0.801)
    const snapshot = structuredClone(first)
    const second = createPrivateInspectionSample()
    const camera = second.camera
    const kinematics = second.kinematics
    const depth = second.kinematics.spaceDepth
    expect(second.camera).not.toBe(first.camera)
    expect(second.kinematics).not.toBe(first.kinematics)
    expect(depth).not.toBe(first.kinematics.spaceDepth)
    for (const p of [0.84, 0.79, 0.91, 0.801]) {
      expect(samplePrivateInspection(p, NARROW, second)).toBe(second)
      expect(second.camera).toBe(camera)
      expect(second.kinematics).toBe(kinematics)
      expect(second.kinematics.spaceDepth).toBe(depth)
      expect(first).toEqual(snapshot)
    }
  })

  it('preserves the existing shaft sampler and machining-rate API at matched master seconds', () => {
    const original = createShaftKinematicsFrame()
    for (let i = 0; i <= 250; i++) {
      const sample = at(0.735 + (0.94 - 0.735) * i / 250)
      expect(sample.kinematics).toEqual(sampleShaftKinematics(sample.subjectTime, original))
      expect(sample.machiningRate).toBe(machiningRateAt(sample.subjectTime))
      expect(sample.machiningRate).toBe(sample.kinematics.machiningRate)
    }
  })

  it.each([DESKTOP, NARROW])('retains the baseline camera at clear endpoint seams at aspect %s', (aspect) => {
    const baseline = createShaftCameraSample()
    for (const progress of [0, 0.735, 0.925, 0.94, 1]) {
      const sample = at(progress, aspect)
      const expectedTime = progress <= 0.735 ? 0 : 43
      expect(sample.arcWeight).toBeLessThan(1e-20)
      expect(sample.hobSwingWeight).toBe(0)
      sampleShaftCamera(expectedTime, aspect, sample.kinematics, baseline)
      for (const key of Object.keys(baseline) as (keyof typeof baseline)[]) {
        if (key === 'valid') expect(sample.camera[key]).toBe(baseline[key])
        else expect(sample.camera[key]).toBeCloseTo(baseline[key], 12)
      }
    }
  })

  it('deep-freezes the data-only authored arc', () => {
    expect(Object.isFrozen(CutterCameraArc)).toBe(true)
    expect(CutterCameraArc.length).toBeGreaterThanOrEqual(2)
    for (const keyframe of CutterCameraArc) {
      expect(Object.isFrozen(keyframe)).toBe(true)
      expect(Object.isFrozen(keyframe.target)).toBe(true)
      expect(Object.isFrozen(keyframe.targetNarrow)).toBe(true)
      expect(keyframe.distance).toBeGreaterThan(0)
    }
  })

  it.each([DESKTOP, NARROW])('has observable translation AND orientation in the stable slow window at aspect %s', (aspect) => {
    // Plain CPU motion witnesses only: no projected proxies or framing acceptance.
    const samples = [0.801, 0.809, 0.817, 0.825, 0.831].map(p => at(p, aspect))
    const baseline = createShaftCameraSample()
    for (const sample of samples) {
      expect(sample.subjectTime).toBeGreaterThan(7.2)
      expect(sample.subjectTime).toBeLessThan(9.6)
      expect(sample.machiningRate).toBeLessThanOrEqual(0.22)
      expect(sample.arcWeight).toBe(1)
      sampleShaftCamera(sample.subjectTime, aspect, sample.kinematics, baseline)
      // Runtime framing may author a different target/FOV; preserve baseline up and
      // follow channels while the independent browser gate measures the actual disc.
      for (const key of ['ux', 'uy', 'uz', 'followAzimuth', 'followWeight'] as const) {
        expect(sample.camera[key]).toBeCloseTo(baseline[key], 12)
      }
      expect(sample.camera.uy).toBe(1)
    }
    for (let i = 1; i < samples.length; i++) {
      const a = samples[i - 1]
      const b = samples[i]
      expect(positionDistance(a, b)).toBeGreaterThan(0.001)
      expect(orientationAngle(a, b)).toBeGreaterThan(0.005)
      // The camera clock advances independently of slowed machining time.
      expect((b.cameraTime - a.cameraTime) / (b.kinematics.machining - a.kinematics.machining)).toBeGreaterThan(5)
    }
  })

  it.each([DESKTOP, NARROW])('has finite normalized orientation and nondegenerate look/up throughout at aspect %s', (aspect) => {
    for (let i = 0; i <= 500; i++) {
      const sample = at(i / 500, aspect)
      const c = sample.camera
      expect(sample.arcWeight).toBeGreaterThanOrEqual(0)
      expect(sample.arcWeight).toBeLessThanOrEqual(1)
      for (const value of Object.values(c)) {
        if (typeof value === 'number') expect(Number.isFinite(value)).toBe(true)
      }
      expect(c.valid).toBe(true)
      expect(Math.hypot(c.dx, c.dy, c.dz)).toBeCloseTo(1, 12)
      expect(Math.hypot(c.ux, c.uy, c.uz)).toBeCloseTo(1, 12)
      const length = Math.hypot(c.tx - c.px, c.ty - c.py, c.tz - c.pz)
      expect(length).toBeGreaterThan(0.1)
      expect(c.dx).toBeCloseTo((c.tx - c.px) / length, 12)
      expect(c.dy).toBeCloseTo((c.ty - c.py) / length, 12)
      expect(c.dz).toBeCloseTo((c.tz - c.pz) / length, 12)
      const upDot = c.dx * c.ux + c.dy * c.uy + c.dz * c.uz
      expect(Math.abs(upDot)).toBeLessThan(0.95)
      expect(c.fov).toBeGreaterThan(0)
      expect(c.fov).toBeLessThan(180)
    }
  })

  it.each([DESKTOP, NARROW])('is C1 at master knots and arc entry/exit seams at aspect %s', (aspect) => {
    const seams = [...new Set([...KNOTS.map(([p]) => p), ...CAMERA_SEAMS,
      progressAtTime(2), progressAtTime(6.5), progressAtTime(10.3),
      progressAtTime(15), progressAtTime(16)])]
    // Small enough to distinguish a seam from the compressed exit's curvature.
    const h = 1e-9
    const channels: [string, (s: PrivateInspectionSample) => number, number][] = [
      ['subjectTime', s => s.subjectTime, 0.03],
      ['cameraTime', s => s.cameraTime, 0.03],
      ['arcWeight', s => s.arcWeight, 0.002],
      ...(['px', 'py', 'pz', 'tx', 'ty', 'tz'] as const).map(key =>
        [key, (s: PrivateInspectionSample) => s.camera[key], 0.001] as [string, (s: PrivateInspectionSample) => number, number]),
      ...(['dx', 'dy', 'dz', 'ux', 'uy', 'uz'] as const).map(key =>
        [key, (s: PrivateInspectionSample) => s.camera[key], 0.005] as [string, (s: PrivateInspectionSample) => number, number]),
      ['fov', s => s.camera.fov, 0.05],
    ]
    for (const p of seams) {
      const left = at(p - h, aspect)
      const center = at(p, aspect)
      const right = at(p + h, aspect)
      for (const [name, read, tolerance] of channels) {
        const leftRate = (read(center) - read(left)) / h
        const rightRate = (read(right) - read(center)) / h
        expect(Math.abs(read(right) - read(left)), `${name} C0 at ${p}`).toBeLessThan(2e-5)
        expect(Math.abs(rightRate - leftRate), `${name} C1 at ${p}`).toBeLessThan(tolerance)
      }
    }
  })
})

import {
  DRAWING_INTRO_WINDOW,
  drawingIntroState,
  INTRO_PHASES,
  type IntroState,
} from '../drawing/introTimeline'
import { GROUP_COUNT, sheetReveal } from '../drawing/sheetCamera'

/** Private semantic coordinates map to the unchanged lower-level physical channels. */
const INTRO_KNOTS = [
  [0, 0], [0.265, 0.38], [0.32, 0.45], [0.36, 0.66],
  [0.395, 0.79], [0.42, 0.84], [0.435, 0.9], [0.46, 1],
] as const

/** Measured from jgun-sheet-v2.bin.gz: group 15 starts drawing at key .67 -> t .3835. */
export const DEFAULT_FINAL_INK_T = 0.3835

function revealBoundary(group: number, complete: boolean, scratch: number[]): number {
  const read = (t: number) => sheetReveal(t, scratch)[group]
  const atZero = read(0), atOne = read(1)
  if (complete) {
    if (atZero >= 1) return 0
    if (atOne < 1) return 1
  } else {
    if (atZero > 0) return 0
    if (atOne <= 0) return 1
  }
  let low = 0, high = 1
  for (let i = 0; i < 24; i++) {
    const mid = (low + high) / 2
    if (complete ? read(mid) < 1 : read(mid) <= 0) low = mid
    else high = mid
  }
  return (low + high) / 2
}

/**
 * Read the actual baked line instances and convert the latest stroke START
 * to intro time through the unchanged shared reveal map. The lamp therefore
 * fails while that final line is being drawn, not after it completes.
 * This is bake-time only; normal sampling stays allocation-free.
 */
export function finalInkTimeFromStyles(
  styles: ArrayLike<number>,
  stride = 4,
  fallback = DEFAULT_FINAL_INK_T,
): number {
  if (!Number.isFinite(stride) || stride < 4 || !Number.isInteger(stride)) {
    throw new RangeError('Final-ink style stride must be an integer >= 4')
  }
  if (styles.length % stride !== 0) throw new RangeError('Final-ink style buffer is not aligned')
  const scratch = new Array<number>(GROUP_COUNT).fill(1)
  const starts = new Array<number>(GROUP_COUNT).fill(1)
  const ends = new Array<number>(GROUP_COUNT).fill(1)
  let latest = 0
  for (let i = 0; i < styles.length; i += stride) {
    const group = Math.round(styles[i + 1])
    if (group === 0) continue
    if (group < 0 || group >= GROUP_COUNT) throw new RangeError('Final-ink group is out of range')
    if (starts[group] === 1 && ends[group] === 1 && revealBoundary(group, false, scratch) === 1) continue
    if (starts[group] === 1) starts[group] = revealBoundary(group, false, scratch)
    if (ends[group] === 1) ends[group] = revealBoundary(group, true, scratch)
    const key = styles[i + 2]
    if (key <= 0 || key >= 1) continue
    latest = Math.max(latest, starts[group] + key * (ends[group] - starts[group]))
  }
  return latest > 0 ? latest : fallback
}

export function openingTimeAt(progress: number): number {
  if (!Number.isFinite(progress)) throw new RangeError('Opening progress must be finite')
  const p = Math.max(0, Math.min(1, progress))
  if (p >= 0.46) return 1
  let i = 0
  while (i < INTRO_KNOTS.length - 2 && p >= INTRO_KNOTS[i + 1][0]) i++
  const [a, t0] = INTRO_KNOTS[i], [b, t1] = INTRO_KNOTS[i + 1]
  const u = Math.max(0, Math.min(1, (p - a) / (b - a)))
  return t0 + (t1 - t0) * u * u * (3 - 2 * u)
}

function applyPrivateLampTiming(state: IntroState, finalInkT: number, crossing: number): void {
  if (finalInkT >= INTRO_PHASES.flickerStart) return
  if (state.t < finalInkT) {
    state.lampPower = 1
  } else if (state.t < INTRO_PHASES.blackoutStart) {
    const mapped = INTRO_PHASES.flickerStart
      + (state.t - finalInkT) * (INTRO_PHASES.blackoutStart - INTRO_PHASES.flickerStart)
        / (INTRO_PHASES.blackoutStart - finalInkT)
    state.lampPower = drawingIntroState(mapped * DRAWING_INTRO_WINDOW.releaseEnd, crossing).lampPower
  }
  state.blackout = state.lampPower <= 0.03 ? 1 : 0
  state.illumination = state.lampPower * state.pbr
}

export function sampleOpening(progress: number, crossing = 0.9, finalInkT = DEFAULT_FINAL_INK_T): IntroState {
  if (!Number.isFinite(finalInkT) || finalInkT < 0 || finalInkT > 1) {
    throw new RangeError('Final ink time must be finite in [0, 1]')
  }
  const state = drawingIntroState(openingTimeAt(progress) * DRAWING_INTRO_WINDOW.releaseEnd, crossing)
  applyPrivateLampTiming(state, finalInkT, crossing)
  return state
}

/** Page-owned cache: a newly solved bake must invalidate a stationary frame. */
export function createOpeningSampler() {
  let lastProgress = NaN, lastCrossing = NaN, lastFinalInkT = NaN
  let result: IntroState | null = null
  return (progress: number, crossing = 0.9, finalInkT = DEFAULT_FINAL_INK_T): IntroState => {
    if (result === null || progress !== lastProgress || crossing !== lastCrossing || finalInkT !== lastFinalInkT) {
      const next = sampleOpening(progress, crossing, finalInkT)
      lastProgress = progress; lastCrossing = crossing; lastFinalInkT = finalInkT; result = next
    }
    return result
  }
}

import { SHEET_ZONES } from '../drawing/drawingGeometry'
import { fitTitleText } from '../drawing/sheet/composeSheet'
import { GROUP, InkBuilder, PEN_COLOR, withPenColor, type InkText } from '../drawing/sheet/ink'
import { OWNER_NOTES, OWNER_TITLE } from '../drawing/sheet/ownerAnnotations'
import { handwrite, strokeLength, supportedText, type HandStroke } from '../drawing/sheet/handwriting'

/**
 * JG-038 lane A — private drafting-sheet content corrections (owner decisions D1.1-D1.3, 2026-10-15).
 *
 * RuntimeWorld wires this as bakeSheet's optional `content` hook. bakeSheet applies it to the
 * composed ink AFTER composition / precompute install and BEFORE any mesh, text layer or
 * fragment print consumes it, so both the live CAD bake and the loaded binary precompute are
 * corrected at one point. The shared sheet defaults are untouched: this module never mutates
 * its input (composeSheet memoizes the builder across bakes) and is idempotent, so a precompute
 * asset exported with the hook applied can safely pass through the hook again at runtime.
 *
 * Corrections:
 * - D1.1 title: "Digital Systems Architect" -> "MECHANICAL DESIGNER / SYSTEMS ARCHITECT".
 * - D1.2 naming: "Torque Gun" -> "Torque Wrench" in private drawing text.
 * - D1.3 output annotation: "Run FEA." moves to its own bottom line in red. Red is the exact
 *   strikeout colour (InkText color 'red' renders through uInkRed = INK_RED, the same uniform
 *   the 4140/4340/C300 strikeout paths use), and path-drawn glyphs carry the exact strikeout
 *   pen half-width (RED_STRIKE_PEN_HALF_WIDTH). Font lettering weight is intrinsic to the
 *   handwriting font; InkText has no per-text stroke width, so exact lineweight parity applies
 *   to the path glyphs (the words' period) while letters match the strikeout colour exactly.
 *   The hand writes capitals, consistent with every word already on the note.
 */

/** Private content variant marker version (bakeSheet stamps stats.privateContent when wired). */
export const PRIVATE_SHEET_CONTENT_VERSION = 1

/** D1.1 — owner-verbatim corrected title, '/'-separated per the owner's offered separators. */
export const PRIVATE_TITLE_TEXT = 'MECHANICAL DESIGNER / SYSTEMS ARCHITECT'

/** D1.3 — the moved annotation keeps its exact authored words; only placement and colour change. */
export const RUN_FEA_LINE = 'Run FEA.'

/**
 * Exact red strikeout pen half-width (sheet metres) of the 4140/4340/C300 strikeout paths in
 * ownerAnnotations.ts (`pen(ink, strikes, GROUP.noteInput, 0.54, 0.68, PEN_COLOR.red, 0.00026)`).
 * Path-drawn glyphs of the red RUN FEA. line emit with this same width and PEN_COLOR.red.
 * Mirrored here because the source constant is module-private.
 */
export const RED_STRIKE_PEN_HALF_WIDTH = 0.00026

/** Deterministic hand-variation seed for the new red line (51-53 are the existing note lines). */
const RUN_FEA_SEED = 54

/** Reveal span of the output note's hand (group-reveal fractions, mirroring ownerAnnotations). */
const NOTE_KEY_START = 0.26
const NOTE_KEY_END = 1.0
/** Fraction of the note reveal given to the red bottom line; existing keys rescale uniformly. */
const RUN_FEA_KEY_SPAN = 0.08

const normalize = (text: string): string => text.replace(/\s+/g, ' ').trim().toUpperCase()

const torqueWrench = (text: string): string =>
  text.replace(/torque(\s+)gun/gi, (match, gap: string) =>
    match === match.toUpperCase() ? `TORQUE${gap}WRENCH` : `Torque${gap}Wrench`)

interface Cell { x: number; y: number; w: number; h: number }

/**
 * Mirror of the composeSheet title-block right-column cells for the role and project rows
 * (composeSheet title-block section: split at 46% width, rows at 52/34/17% height, role cell
 * top-0.0275 with h 0.008, project cell rows[0]..top-0.0285). Needed because the binary
 * precompute does not serialize fitCell. Guarded: used only when the item sits inside the
 * mirrored cell, so a composeSheet layout drift falls back to the conservative shrink below
 * instead of a wrong fit.
 */
function titleBlockCells(): { role: Cell; project: Cell } {
  const tb = SHEET_ZONES.titleBlock
  const split = tb.x + tb.w * 0.46
  const right = tb.x + tb.w
  const top = tb.y + tb.h
  const rows0 = tb.y + tb.h * 0.52
  return {
    role: { x: split, y: top - 0.0275, w: right - split, h: 0.008 },
    project: { x: split, y: rows0, w: right - split, h: top - 0.0285 - rows0 },
  }
}

const withinCell = (item: InkText, cell: Cell): boolean =>
  item.x >= cell.x && item.x <= cell.x + cell.w && item.y >= cell.y && item.y <= cell.y + cell.h

/** Replace one title-block item's text and refit under composeSheet's own fit policy. */
function replaceAndRefit(item: InkText, next: string, cell: Cell | undefined): void {
  const widthEm = (lines: string[]) =>
    Math.max(...lines.map((line) => line.length * (0.7 + (item.letterSpacing ?? 0.02))))
  const oldWidth = widthEm(item.text.split('\n'))
  item.text = next
  if (item.fitCell) {
    fitTitleText(item, item.fitCell)
    return
  }
  if (cell && withinCell(item, cell)) {
    fitTitleText(item, cell)
    return
  }
  // Conservative fallback (no trustworthy cell): shrink by the em-width ratio, never grow.
  const ratio = oldWidth > 0 ? Math.min(1, oldWidth / widthEm(next.split('\n'))) : 1
  item.size *= ratio
}

const median = (values: number[]): number => {
  const sorted = [...values].sort((a, b) => a - b)
  return sorted.length ? sorted[Math.floor(sorted.length / 2)] : 0
}

interface NoteGeometry {
  originX: number
  lowestBaseline: number
  pitch: number
  capHeight: number
  rotation: number
  keyStart: number
  keyEnd: number
}

const noteLetters = (texts: readonly InkText[]): InkText[] =>
  texts.filter((t) => t.group === GROUP.noteOutput && t.weight === 'handwriting')

/** Cluster the hand into written lines by baseline proximity (per-letter jitter is tiny). */
function clusterByBaseline(letters: readonly InkText[]): InkText[][] {
  const sorted = [...letters].sort((a, b) => b.y - a.y)
  const gaps: number[] = []
  for (let i = 1; i < sorted.length; i += 1) {
    const d = sorted[i - 1].y - sorted[i].y
    if (d > 1e-6) gaps.push(d)
  }
  const pitch = gaps.length ? median(gaps) : 0.0068
  const clusters: InkText[][] = []
  for (const letter of sorted) {
    const cluster = clusters.find((c) => Math.abs(letter.y - c[0].y) <= pitch * 0.5)
    if (cluster) cluster.push(letter)
    else clusters.push([letter])
  }
  return clusters
}

function deriveNoteGeometry(clusters: InkText[][], letters: readonly InkText[]): NoteGeometry {
  const baselines = clusters.map((c) => median(c.map((l) => l.y))).sort((a, b) => b - a)
  const pitch = baselines.length > 1 ? baselines[0] - baselines[baselines.length - 1] : 0.0068
  const linePitch = baselines.length > 2 ? (baselines[0] - baselines[baselines.length - 1]) / (baselines.length - 1) : pitch
  return {
    originX: Math.min(...letters.map((l) => l.x)),
    lowestBaseline: baselines[baselines.length - 1],
    pitch: linePitch,
    capHeight: median(letters.map((l) => l.size)),
    rotation: median(letters.map((l) => l.rotation ?? 0)),
    keyStart: Math.min(...letters.map((l) => l.key)),
    keyEnd: Math.max(...letters.map((l) => l.key + (l.dur ?? 0))),
  }
}

/**
 * Emit "RUN FEA." hand strokes as the note's own bottom line: red font letters through the
 * strikeout red, path-fallback glyphs (no font contour exists for '.') as red pen paths at the
 * exact strikeout half-width. Key/dur weighting mirrors ownerAnnotations' pen() walk.
 */
function appendRunFeaLine(out: InkBuilder, geometry: NoteGeometry): void {
  const written = handwrite(RUN_FEA_LINE, {
    x: geometry.originX,
    y: geometry.lowestBaseline - geometry.pitch,
    capHeight: geometry.capHeight,
    penHalfWidth: RED_STRIKE_PEN_HALF_WIDTH,
    seed: RUN_FEA_SEED,
    rotation: geometry.rotation,
  })
  const keyStart = geometry.keyEnd - (geometry.keyEnd - geometry.keyStart) * RUN_FEA_KEY_SPAN
  const total = strokeLength(written.strokes) || 1
  let walked = 0
  for (const stroke of written.strokes as HandStroke[]) {
    const len = strokeLength([stroke])
    const key = keyStart + (walked / total) * (geometry.keyEnd - keyStart)
    const dur = Math.max(1e-4, (len / total) * (geometry.keyEnd - keyStart))
    if (stroke.letter) {
      const letter = stroke.letter
      out.text({
        text: letter.ch, x: letter.x, y: letter.y, size: letter.capHeight, group: GROUP.noteOutput,
        key, dur, weight: 'handwriting', color: 'red', scaleX: letter.scaleX, rotation: letter.rotation,
        anchorX: 'left', anchorY: 'baseline', letterSpacing: 0,
      })
    } else {
      out.path(stroke.points, RED_STRIKE_PEN_HALF_WIDTH * (stroke.pressure ?? 1), GROUP.noteOutput, key, dur,
        withPenColor(0, PEN_COLOR.red))
    }
    walked += len
  }
}

interface NotePlan {
  geometry: NoteGeometry
  /** Line-1 letters of the moved "Run FEA." words (dropped from the first line). */
  drop: Set<InkText>
  /** Remaining line-1 letters shifted left to the note origin. */
  shift: InkText[]
  dx: number
}

/**
 * Plan the D1.3 correction from the composed letter stream, or null when the note is absent,
 * already corrected (red line present), or does not spell the expected words (fail-safe: the
 * title/naming passes still run, the note is left as authored).
 */
function planRunFea(texts: readonly InkText[]): NotePlan | null {
  const letters = noteLetters(texts)
  if (!letters.length || letters.some((l) => l.color === 'red')) return null
  const clusters = clusterByBaseline(letters)
  const firstLine = clusters[0]
  const ordered = letters.filter((l) => firstLine.includes(l))
  const moveChars = [...RUN_FEA_LINE.replace(/ /g, '')].map((c) => c.toUpperCase())
  const drop = ordered.slice(0, moveChars.length)
  if (drop.map((l) => l.text.toUpperCase()).join('') !== moveChars.join('')) return null
  const geometry = deriveNoteGeometry(clusters, letters)
  if (geometry.keyEnd - geometry.keyStart < 0.01) return null
  const shift = ordered.slice(moveChars.length)
  const dx = shift.length ? geometry.originX - Math.min(...shift.map((l) => l.x)) : 0
  return { geometry, drop: new Set(drop), shift, dx }
}

/**
 * Apply the private content corrections to a cloned builder. The input is never mutated and
 * the output is stable under re-application (an already-corrected sheet passes through).
 */
export function applyPrivateSheetContent(source: InkBuilder): InkBuilder {
  const out = new InkBuilder()
  // Avoid spread's argument limit on the full CAD line set (same pattern as drawingCache).
  for (const n of source.segs) out.segs.push(n)
  for (const n of source.fills) out.fills.push(n)
  const cells = titleBlockCells()
  const plan = planRunFea(source.texts)
  const rescale = plan
    ? (() => {
      const { keyStart, keyEnd } = plan.geometry
      const redStart = keyEnd - (keyEnd - keyStart) * RUN_FEA_KEY_SPAN
      return (redStart - keyStart) / (keyEnd - keyStart)
    })()
    : 1
  for (const item of source.texts) {
    const clone = { ...item }
    // D1.1 — owner title (skip when already corrected: idempotent re-application).
    if (normalize(clone.text) === normalize(OWNER_TITLE.role)
      && normalize(clone.text) !== normalize(PRIVATE_TITLE_TEXT)) {
      replaceAndRefit(clone, PRIVATE_TITLE_TEXT, cells.role)
    }
    // D1.2 — private drawing naming.
    if (/torque\s+gun/i.test(clone.text)) replaceAndRefit(clone, torqueWrench(clone.text), cells.project)
    // D1.3 — output note: drop the moved words, re-align the rest, rescale reveal keys,
    // then append the red bottom line after the loop.
    if (plan && clone.group === GROUP.noteOutput && clone.weight === 'handwriting') {
      if (plan.drop.has(item)) continue
      if (plan.shift.includes(item)) clone.x += plan.dx
      clone.key = plan.geometry.keyStart + (clone.key - plan.geometry.keyStart) * rescale
      if (clone.dur !== undefined) clone.dur *= rescale
    }
    out.texts.push(clone)
  }
  if (plan && supportedText(RUN_FEA_LINE)) appendRunFeaLine(out, plan.geometry)
  return out
}
